insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049226', '$r(1)=(2,3,-2)$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Uma reta espacial fica determinada por um ponto e um vetor diretor não nulo. A forma paramétrica soma ao ponto um múltiplo real da direção; por isso, substituir o parâmetro ou comparar componentes permite verificar cada resultado sem ambiguidade. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
