insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049331', '$(4,2,-2)$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000493311', '40000000-0000-4000-8000-000000049331', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000493312', '40000000-0000-4000-8000-000000049331', 'Leia a direção', '$d=(2,1,-1).$', 2), ('70000000-0000-4000-8000-000000493313', '40000000-0000-4000-8000-000000049331', 'Use um mesmo fator', '$2d=(4,2,-2).$', 3), ('70000000-0000-4000-8000-000000493314', '40000000-0000-4000-8000-000000049331', 'Conclua', 'Como todos os componentes foram multiplicados por 2, a direção é a mesma.', 4), ('70000000-0000-4000-8000-000000493315', '40000000-0000-4000-8000-000000049331', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
