insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000493401', '40000000-0000-4000-8000-000000049340', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000493402', '40000000-0000-4000-8000-000000049340', 'Extraia o normal', '$n_{\pi}=(6,1,-1).$', 2), ('70000000-0000-4000-8000-000000493403', '40000000-0000-4000-8000-000000049340', 'Compare', '$d=n_{\pi}.$', 3), ('70000000-0000-4000-8000-000000493404', '40000000-0000-4000-8000-000000049340', 'Conclua', 'O diretor da reta tem a direção normal ao plano; portanto, a reta o corta perpendicularmente.', 4), ('70000000-0000-4000-8000-000000493405', '40000000-0000-4000-8000-000000049340', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
