insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000493451', '40000000-0000-4000-8000-000000049345', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000493452', '40000000-0000-4000-8000-000000049345', 'Liste os normais', '$n_1=(7,1,0), n_2=(1,-7,0).$', 2), ('70000000-0000-4000-8000-000000493453', '40000000-0000-4000-8000-000000049345', 'Calcule o produto', '$n_1 \cdot n_2=7-7=0.$', 3), ('70000000-0000-4000-8000-000000493454', '40000000-0000-4000-8000-000000049345', 'Conclua', 'Normais ortogonais determinam planos perpendiculares.', 4), ('70000000-0000-4000-8000-000000493455', '40000000-0000-4000-8000-000000049345', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
