insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000493501', '40000000-0000-4000-8000-000000049350', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000493502', '40000000-0000-4000-8000-000000049350', 'Leia o normal', '$n_1=(9,2,-1).$', 2), ('70000000-0000-4000-8000-000000493503', '40000000-0000-4000-8000-000000049350', 'Compare candidatos', 'O primeiro mantém os mesmos coeficientes.', 3), ('70000000-0000-4000-8000-000000493504', '40000000-0000-4000-8000-000000049350', 'Conclua', 'Ele tem a mesma orientação e termo independente diferente.', 4), ('70000000-0000-4000-8000-000000493505', '40000000-0000-4000-8000-000000049350', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
